static inline FontMetrics FontMetricsFor(FontSize size) {
    if ((int)size < 0 || (int)size >= 4) return g_fontMetrics[0];
    return g_fontMetrics[size];
}

static inline int FontCellHeight(FontSize size) {
    return FontMetricsFor(size).ch;
}

static inline int FontTextWidth(const char *s, FontSize size) {
    if (!s) return 0;
    return (int)strlen(s) * FontMetricsFor(size).cw;
}

